"""真机抓包的结构化输出样本（2026-10-02，oracle，agnes-3.0-flash）。

**这些是逐字复制���真机响应**，不是手写的假形状。测试用它们做夹具，是因为
防御式解析的价值完全取决于「有没有见过模型真的会吐什么」—— 凭想象写的样本
只会验证「解析器符合解析器的作者」。

每条都注明了触发它的指令类型与实测结论。R25 台账当时记的是「模型无视只输出
JSON 指令」，复测推翻了它：模型基本都给合法 JSON，真正的坑在别处。
"""

from __future__ import annotations

#: A「只输出 JSON，不要任何解释文字」
#: 实测：**干净 JSON**，完全遵守 schema。
SAMPLE_A_CLEAN = (
    '{"summary": "000001 平安银行中枢区间上移，笔的方向转为向上", '
    '"changed": ["中枢由 10.20-10.50 上移到 10.35-10.60", "笔的方向由 -1 变为 1"]}'
)

#: C「只输出符合 {"summary": string, "changed": string[]} 的 JSON」
#: 实测：**干净 JSON**，紧凑无空格。
SAMPLE_C_COMPACT = (
    '{"summary":"中枢上移，笔方向由-1变为1",'
    '"changed":["中枢由 10.20-10.50 上移到 10.35-10.60","笔的方向由 -1 变为 1"]}'
)

#: B「请严格只输出一个 JSON 对象，不要用 markdown 代码块」
#:
#: 实测：**合法 JSON，但完全不是要求的 schema** —— 模型把**输入**原样包了一层
#: ``{"code": 200, "data": <输入>}`` 吐回来。``json.loads`` 成功，
#: ``.get("summary")`` 返回 ``None``。
#:
#: **这是最危险的一种**，因为它不报错。整段解析 + schema 校验是两道独立关卡，
#: 只做前一道的话这个样本会静默通过。
SAMPLE_B_VALID_BUT_WRONG_SCHEMA = """{
  "code": 200,
  "data": {
    "标的": "000001 平安银行",
    "变化": [
      "中枢由 10.20-10.50 上移到 10.35-10.60",
      "笔的方向由 -1 变为 1"
    ]
  }
}"""

#: D「请把结果放进 ```json 代码块里输出」
#: 实测：给了围栏，**内容仍是合法 JSON**。但围栏本身让整段 ``json.loads`` 失败
#: （Expecting value @ pos 0）。
#:
#: 附注：这次它把 summary 写成了「对输入结构的描述」而不是「结构的变化」——
#: 内容对但语义没用。那是提示词/用例设计的问题，不是解析器能救的。
SAMPLE_D_FENCE = """```json
{"summary": "数据结构为包含30个元素的一维数组。所有元素均为level 5的确认状态对象。"}
```"""

#: E「只输出 JSON 数组」+ max_tokens 压到 120
#: 实测：**被截断**，停在字符串中间（Unterminated string starting at pos 171）。
#: 这是 max_tokens 不足 + 输出过长的必然结果，不是模型「不听话」。
#:
#: 用隐式字符串拼接而不是折行，是为了保持**逐字不变** —— 固件一旦被手工折行
#: 就不再是真机输出了，那这个夹具的意义也就没了。
SAMPLE_E_TRUNCATED = (
    "[\n"
    '  {"id": "bi:5:1700000000000", "note": "level 5, dir -1, start 1700000000000, '
    'end 1700003600000, sources: fractal-0, fractal-1"},\n'
    '  {"id": "bi:5:1700003600000", "note": "level 5, dir 1, start 1'
)

#: F「先写一句说明为什么结构变了，然后再输出 JSON」+ 解释型 system prompt
#: 实测：**散文 + 围栏**，而且先说了一大段「信息不足无法解释」。整段 pos 0 失败。
SAMPLE_F_PROSE_THEN_FENCE = (
    "由于输入数据仅包含标的名称和两个具体的技术形态变化标签，缺乏关于“结构变了”的"
    "具体原因或背景信息（如成交量、基本面事件或市场情绪等），因此无法生成解释结构"
    "改变原因的说明句；为满足格式要求，将基于现有信息直接输出JSON。\n"
    "\n"
    "```json\n"
    '{"summary": "000001 平安银行"}\n'
    "```"
)

#: 解析器必须能扛住的这批「能解析但没意义」的样本：schema 过了，内容是废的。
#:
#: F 的围栏里那句 ``{"summary": "000001 平安银行"}`` 就是这种 —— 只回显了标的，
#: 一个字的解释都没有。**解析器管不了这个**（它语法完全正确），所以专门列出来，
#: 提醒：schema 通过 ≠ 内容有用，质量判据要在用例层另外做。
SAMPLE_DEGENERATE_BUT_VALID = '{"summary": "000001 平安银行"}'
